await page.evaluate(async () => { const a = [...document.querySelectorAll('a')].find(a => /tutorial/i.test(a.textContent)); if(a) location.href = a.href; });
await page.getByRole('link', {name: /Gil|visual|play.engine|object.process/i}).first().click();
await page.evaluate(() => { const text=document.body.innerText; const match=text.match(/(?:Object[ -]Process Methodology(?:\s*\(OPM\))?|Play[ -]?Engine|Live Sequence Charts(?:\s*\(LSCs?\))?)/i); return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:text.slice(0,1200),values:match?[match[0]]:[],answer:match?match[0]:text}; });

await page.goto('http://www.icse-conferences.org/2002/index.html');
await page.evaluate(async () => { const parse=(html,url)=>{const d=new DOMParser().parseFromString(html,'text/html');return {text:d.body.innerText||d.body.textContent,links:[...d.querySelectorAll('a[href]')].map(a=>({text:a.textContent,url:new URL(a.getAttribute('href'),url).href}))}}; const base=location.href; const first=parse(document.documentElement.outerHTML,base); const queue=first.links.filter(a=>/tutorial/i.test(a.text+' '+a.url)); const seen=new Set(); let target=''; for(let i=0;i<queue.length&&i<45;i++){const item=queue[i];if(seen.has(item.url))continue;seen.add(item.url);try{const r=await fetch(item.url);const p=parse(await r.text(),item.url); if(/Joseph\s+Gil/i.test(p.text)&&/visual|modeling|modelling/i.test(p.text)){target=item.url;const detail=p.links.find(a=>/Gil|visual|LePUS|constraint|modeling complex/i.test(a.text)&&!seen.has(a.url));if(detail){queue.unshift();const rr=await fetch(detail.url);const pp=parse(await rr.text(),detail.url);if(/Gil/i.test(pp.text))target=detail.url;}break;}for(const a of p.links)if(/tutorial|Gil|visual|LePUS|constraint/i.test(a.text+' '+a.url)&&a.url.startsWith('http')&&!seen.has(a.url))queue.push(a);}catch(e){}} if(target)location.href=target;else if(queue.length)location.href=queue[0].url; });
await page.evaluate(() => {const text=document.body.innerText;const match=text.match(/LePUS|Visual Contract Language(?:\s*\(VCL\))?|Constraint Diagrams|(?:Object[ -]Process Methodology)(?:\s*\(OPM\))?|Live Sequence Charts(?:\s*\(LSCs?\))?|[A-Z][A-Za-z -]{0,50}\(VCL\)/i);return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:text.slice(0,1800),values:match?[match[0]]:[],answer:match?match[0]:text};});

