await page.goto('https://www.ironhidegames.com/Games/junkworld');
await page.evaluate(async () => {
 const parser = new DOMParser();
 const get = async u => parser.parseFromString(await (await fetch(u)).text(), 'text/html');
 const gameText=document.body.innerText;
 let links=[...document.querySelectorAll('a[href]')].map(a=>({url:a.href,text:a.innerText})).filter(a=>/junkworld/i.test(a.text)&&/News/i.test(a.url));
 const news=await get('/News/junkworld');
 links.push(...[...news.querySelectorAll('a[href]')].map(a=>({url:new URL(a.getAttribute('href'),location.origin).href,text:a.textContent})).filter(a=>/Details/.test(a.url)));
 const unique=[...new Map(links.map(a=>[a.url,a])).values()];
 const articles=await Promise.all(unique.map(async a=>{const d=await get(a.url);return {...a,body:d.body.innerText||d.body.textContent};}));
 window.__research={gameText,articles};
 const relevant=articles.filter(a=>/January|2024|September|launch/i.test(a.body));
 const dest=relevant.find(a=>/January/.test(a.body)&&/2024/.test(a.body))||relevant.find(a=>/update/i.test(a.text));
 if(dest){sessionStorage.setItem('research',JSON.stringify({gameText,articles}));location.href=dest.url;}
});
